import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def can_transform_to_B(N, B):
    for i in range(1, N + 1):
        if B[i - 1] != i:
            return "NO"
    return "YES"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    T = int(data[index])
    index += 1

    results = []

    for _ in range(T):
        N = int(data[index])
        index += 1
        B = list(map(int, data[index:index + N]))
        index += N

        result = can_transform_to_B(N, B)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
